 ("estimate when empty", "if ($objectsToProcess > 0) {\n\t\t\t$this->estimatedChunks", "if ($objectsToProcess >= 0 && $chunkSize > 0) {\n\t\t\t$this->estimatedChunks"),
 ("estimate floor", "$this->estimatedChunks = ceil($objectsToProcess / $chunkSize);", "$this->estimatedChunks = floor($objectsToProcess / $chunkSize);"),
 ("estimate int", "$this->estimatedChunks = ceil($objectsToProcess / $chunkSize);", "$this->estimatedChunks = (int) ceil($objectsToProcess / $chunkSize);"),
 ("band 1000", "if ($objectsToProcess <= 1000) {", "if ($objectsToProcess < 1000) {"),
 ("band 10000", "} elseif ($objectsToProcess <= 10000) {", "} elseif ($objectsToProcess < 10000) {"),
 ("band 50000", "} elseif ($objectsToProcess <= 50000) {", "} elseif ($objectsToProcess < 50000) {"),
