 ("chunk total", "return (float)(($chunkOffset / $this->chunkSize) + 1) . '/' . (float)$this->estimatedChunks;", "return (float)(($chunkOffset / $this->chunkSize) + 1) . '/';"),
 ("processed not summed", "$totals['processed'] += $chunkResult['processed'];", ""),
