 ("multitenancy on", "_multitenancy: false,\n\t\t\tvalidation: true,", "_multitenancy: true,\n\t\t\tvalidation: true,"),
 ("validation off", "validation: true,\n\t\t\tevents: false,", "validation: false,\n\t\t\tevents: false,"),
